@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">@errorMessage</div>
}
else if (allTasks is null)
{
    <p><em>Loading tasks...</em></p>
}
else
{
    <!-- Summary Stats Bar -->
    <div class="d-flex flex-wrap gap-3 mb-3">
        <span class="badge bg-secondary fs-6">Total: @allTasks.Count</span>
        <span class="badge bg-primary fs-6">To Do: @GetColumnTasks("To Do").Count</span>
        <span class="badge bg-warning text-dark fs-6">In Progress: @GetColumnTasks("In Progress").Count</span>
        <span class="badge bg-success fs-6">Done: @GetColumnTasks("Done").Count</span>
        <span class="badge bg-danger fs-6">Overdue: @allTasks.Count(t => t.DueDate.Date < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row">
        @foreach (var column in columns)
        {
            var colTasks = GetFilteredColumnTasks(column);
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@column</strong>
                        <span class="badge bg-secondary">@colTasks.Count</span>
                    </div>
                    <div class="card-body" style="min-height: 200px;">
                        @foreach (var task in colTasks)
                        {
                            <div class="card mb-2">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="card-text mb-1 text-muted small">@task.Assignee</p>
                                    <span class="badge @GetPriorityClass(task.Priority) me-1">@task.Priority</span>
                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    <div class="mt-2 d-flex gap-1">
                                        @if (GetColumnIndex(column) > 0)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    @onclick="() => MoveTask(task.Id, columns[GetColumnIndex(column) - 1])"
                                                    disabled="@isMoving">
                                                &larr; Move Left
                                            </button>
                                        }
                                        @if (GetColumnIndex(column) < columns.Length - 1)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    @onclick="() => MoveTask(task.Id, columns[GetColumnIndex(column) + 1])"
                                                    disabled="@isMoving">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (showAddForm == column)
                        {
                            <div class="card border-primary mb-2">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-1"
                                           @bind="newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary"
                                                @onclick="() => SaveTask(column)"
                                                disabled="@isSaving">
                                            Save
                                        </button>
                                        <button class="btn btn-sm btn-secondary"
                                                @onclick="CancelAdd">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-sm btn-outline-primary w-100"
                                @onclick="() => ShowAddForm(column)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<TaskItem>? allTasks;
    private string? errorMessage;
    private string searchText = string.Empty;

    private readonly string[] columns = ["To Do", "In Progress", "Done"];

    // Add-task form state
    private string? showAddForm;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);
    private bool isSaving;
    private bool isMoving;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        allTasks!.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        allTasks!
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(searchText) ||
                         t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private int GetColumnIndex(string column) => Array.IndexOf(columns, column);

    private static string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        isMoving = true;
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks!.First(t => t.Id == taskId);
            allTasks![allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            isMoving = false;
        }
    }

    private void ShowAddForm(string column)
    {
        showAddForm = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => showAddForm = null;

    private async Task SaveTask(string column)
    {
        if (string.IsNullOrWhiteSpace(newTitle)) return;

        isSaving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            // The service creates with a default status; update to the target column if different.
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            allTasks!.Add(created);
            showAddForm = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }
}

